INSERT INTO destinations (id, name, country, state, description, image_url, best_season, weather_info, estimated_budget_inr, recommended_days, rating, review_count, category, is_international, nearest_airport, nearest_railway, latitude, longitude) VALUES
('goa', 'Goa', 'India', 'Goa', 'Pristine golden beaches, Portuguese heritage architecture, vibrant nightlife, and spice plantations.', 'https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=600&q=80', 'Nov - Feb', '28°C Sunny & Breezy', 18000, 4, 4.8, 320, 'Beach', FALSE, 'Dabolim Airport (GOI)', 'Madgaon Junction', 15.2993, 74.1240),
('manali', 'Manali', 'India', 'Himachal Pradesh', 'High-altitude Himalayan resort town known for snow-capped peaks, Solang Valley adventures, and Rohtang Pass.', 'https://images.unsplash.com/photo-1626621341517-bbf3d9990a23?auto=format&fit=crop&w=600&q=80', 'Oct - Jun', '12°C Crisp Alpine Air', 22000, 5, 4.7, 280, 'Hill Station', FALSE, 'Kullu Manali Airport (KUU)', 'Chandigarh Railway Station', 32.2432, 77.1892),
('shimla', 'Shimla', 'India', 'Himachal Pradesh', 'Capital of Himachal Pradesh, renowned for its colonial architecture, Mall Road, and Ridge views.', 'https://images.unsplash.com/photo-1597074866923-dc0589150358?auto=format&fit=crop&w=600&q=80', 'Mar - Jun', '16°C Cool Mountain Mist', 16000, 3, 4.6, 210, 'Hill Station', FALSE, 'Shimla Airport (SLV)', 'Kalka Railway Station', 31.1048, 77.1734),
('leh_ladakh', 'Leh Ladakh', 'India', 'Ladakh', 'Dramatic high-desert mountain landscapes, crystal Pangong Lake, and historic Tibetan Buddhist monasteries.', 'https://images.unsplash.com/photo-1581793745862-99fde7fa73d2?auto=format&fit=crop&w=600&q=80', 'May - Sep', '14°C Sunny Mountain Sky', 35000, 6, 4.9, 410, 'Adventure', FALSE, 'Kushok Bakula Rimpochee Airport', 'Jammu Tawi Railway Station', 34.1526, 77.5771),
('jaipur', 'Jaipur', 'India', 'Rajasthan', 'Iconic Pink City featuring grand Amber Fort, Hawa Mahal, City Palace, and rich Royal Rajasthani heritage.', 'https://images.unsplash.com/photo-1477587458883-47145ed94245?auto=format&fit=crop&w=600&q=80', 'Oct - Mar', '24°C Pleasant Desert Sun', 15000, 3, 4.7, 340, 'Heritage', FALSE, 'Jaipur International Airport (JAI)', 'Jaipur Junction', 26.9124, 75.7873),
('munnar', 'Munnar', 'India', 'Kerala', 'Rolling emerald tea plantations, foggy hills, Anamudi peak, and serene mountain wildlife sanctuaries.', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=600&q=80', 'Sep - Mar', '19°C Pleasant Tea Breeze', 17000, 4, 4.8, 290, 'Hill Station', FALSE, 'Cochin International Airport (COK)', 'Aluva Railway Station', 10.0889, 77.0595),
('alleppey', 'Alleppey', 'India', 'Kerala', 'Venice of the East, famous for luxury houseboat cruises along calm palm-fringed backwaters.', 'https://images.unsplash.com/photo-1602216056096-3b40cc0c9944?auto=format&fit=crop&w=600&q=80', 'Nov - Feb', '27°C Humid Coastal Breeze', 19000, 3, 4.9, 380, 'Backwaters', FALSE, 'Cochin International Airport (COK)', 'Alleppey Railway Station', 9.4981, 76.3388),
('varanasi', 'Varanasi', 'India', 'Uttar Pradesh', 'Spiritual capital of India along the sacred Ganges river, famous for evening Ganga Aarti and ancient ghats.', 'https://images.unsplash.com/photo-1561361513-2d000a50f0dc?auto=format&fit=crop&w=600&q=80', 'Oct - Mar', '22°C Mild Pleasant Air', 12000, 3, 4.8, 450, 'Spiritual', FALSE, 'Lal Bahadur Shastri Airport (VNS)', 'Varanasi Junction', 25.3176, 82.9739);
INSERT INTO destinations (id, name, country, state, description, image_url, best_season, weather_info, estimated_budget_inr, recommended_days, rating, review_count, category, is_international, currency_code, exchange_rate_inr, nearest_airport, latitude, longitude) VALUES
('maldives', 'Maldives', 'Maldives', 'Malé Atoll', 'Tropical paradise of overwater bungalows, turquoise lagoons, vibrant coral reefs, and private island resorts.', 'https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=600&q=80', 'Nov - Apr', '29°C Tropical Sunshine', 75000, 4, 4.9, 520, 'Luxury', TRUE, 'MVR', 5.42, 'Velana International Airport (MLE)', 3.2028, 73.2207),
('dubai', 'Dubai', 'United Arab Emirates', 'Dubai Emirate', 'Futuristic metropolis famous for Burj Khalifa, desert safaris, luxury shopping malls, and Palm Jumeirah.', 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=600&q=80', 'Nov - Mar', '26°C Warm Desert Sky', 65000, 5, 4.8, 610, 'Luxury', TRUE, 'AED', 22.65, 'Dubai International Airport (DXB)', 25.2048, 55.2708),
('bali', 'Bali', 'Indonesia', 'Bali Province', 'Island of gods featuring lush rice terraces, ancient sea temples, surf beaches, and holistic yoga retreats.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=600&q=80', 'Apr - Oct', '27°C Tropical Island Air', 48000, 5, 4.8, 490, 'Beach', TRUE, 'IDR', 0.0053, 'Ngurah Rai International Airport (DPS)', -8.4095, 115.1889),
('vietnam', 'Da Nang & Hoi An', 'Vietnam', 'Quang Nam', 'Lantern-lit ancient streets, Golden Bridge in Ba Na Hills, marble mountains, and delicious Vietnamese street food.', 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=600&q=80', 'Feb - Aug', '25°C Mild Coastal Sun', 42000, 5, 4.7, 310, 'Culture', TRUE, 'VND', 0.0034, 'Da Nang International Airport (DAD)', 16.0544, 108.2022),
('paris', 'Paris', 'France', 'Île-de-France', 'City of Light renowned for Eiffel Tower, Louvre Museum, Notre-Dame, romantic Seine cruises, and fine pastries.', 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=600&q=80', 'Apr - Oct', '18°C Pleasant European Air', 110000, 6, 4.9, 750, 'Heritage', TRUE, 'EUR', 90.50, 'Charles de Gaulle Airport (CDG)', 48.8566, 2.3522),
('switzerland', 'Interlaken & Lucerne', 'Switzerland', 'Bernese Oberland', 'Alpine wonderland of snow-covered peaks, crystal-clear mountain lakes, scenic panoramic trains, and chocolates.', 'https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=600&q=80', 'May - Oct', '15°C Fresh Alpine Breeze', 135000, 6, 4.9, 820, 'Mountain', TRUE, 'CHF', 94.20, 'Zurich Airport (ZRH)', 46.6863, 7.8632);
